/* C API of the Rust port of `crc4.c`, generated by rust-anything. */
#ifndef CRC4_RS_H
#define CRC4_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint8_t crc4(uint8_t c, uint64_t x, int bits);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint8_t rust_anything_crc4(uint8_t c, uint64_t x, int bits);

#endif /* CRC4_RS_H */
